<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);require dirname(__DIR__).'/src/bootstrap.php';
try{if(!in_array('--apply',$argv,true))throw new RuntimeException('Run with --apply to assign verified original public photos. Existing owner-uploaded photos are preserved.');$dsn=getenv('DATABASE_DSN')?:'sqlite:storage/annam.sqlite';if(!str_starts_with($dsn,'sqlite:'))throw new RuntimeException('This command targets the local SQLite installation only.');$file=substr($dsn,7);if(!str_starts_with($file,'/'))$file=ANNAM_ROOT.'/'.$file;if(!is_file($file))throw new RuntimeException('Local database file missing.');$db=new PDO('sqlite:'.$file,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$db->exec('PRAGMA busy_timeout=15000');$db->exec('PRAGMA foreign_keys=ON');echo json_encode(Annam\PublicMedia::apply($db,Annam\PublicMedia::root()),JSON_THROW_ON_ERROR).PHP_EOL;}catch(Throwable $error){fwrite(STDERR,'Image references were not applied: '.$error->getMessage().PHP_EOL);exit(1);}
